import boto3

def translate_payload(payload, target_language='es'):
    client = boto3.client('translate')
    try:
        response = client.translate_text(Text=payload, SourceLanguageCode='auto', TargetLanguageCode=target_language)
        return response['TranslatedText']
    except client.exceptions.InternalServerException as e:
        print(f"Service error: {e}")
        return None
    except client.exceptions.ServiceError as e:
        print(f"Service error: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error: {e}")
        return None

import boto3

def check_message_safety(message):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_sentiment(
        Text=message,
        LanguageCode='en'
    )
    sentiment = response['Sentiment']
    if sentiment == 'NEGATIVE':
        return False
    else:
        return True

from google.cloud import pubsub_v1

def create_pubsub_client():
    return pubsub_v1.PublisherClient()

def publish_message(project_id, topic_id, data):
    client = create_pubsub_client()
    topic_path = client.topic_path(project_id, topic_id)
    data = data.encode('utf-8')
    future = client.publish(topic_path, data)
    print(f'Published message ID: {future.result()}')

def subscribe_to_topic(project_id, subscription_id):
    client = create_pubsub_client()
    subscription_path = client.subscription_path(project_id, subscription_id)
    response = client.pull(subscription_path, max_messages=10)
    return response.received_messages

def normalize_message(message):
    return message.data.decode('utf-8')

